 const topicNames={all:'Все темы',officer:'Сотрудник',detain:'Задержание',person:'Личность',service:'Должностные',justice:'Правосудие',public:'Безопасность',military:'Военная служба',property:'Имущество',drugs:'Наркотики',weapons:'Оружие',territory:'Территории',admin:'КоАП',upk:'УПК',fsb:'Закон о ФСБ',pgo:'Правила ПГО',upk_detain:'УПК · задержание',upk_rights:'УПК · участники и права',upk_investigation:'УПК · следствие и доказательства',upk_other:'УПК · прочее',fsb_general:'ФСБ · общие положения',fsb_activity:'ФСБ · направления',fsb_power:'ФСБ · полномочия',fsb_control:'ФСБ · контроль',pgo_common:'ПГО · общие правила',pgo_detain:'ПГО · задержание',pgo_fsb:'ПГО · ФСБ',pgo_force:'ПГО · силовые структуры',pgo_other:'ПГО · взаимодействие',pgo_sud:'ПГО · суд и следствие',pgo_traffic:'ПГО · ГИБДД и ФСО',pgo_interrogation:'ПГО · допрос',pgo_search:'ПГО · обыск транспорта',charter:'Устав ФСБ · служба'};
 function group(x){let n=x.number;if(['317','318','319','319.3'].includes(n))return 'officer';if(['319.1','319.2','314'].includes(n))return 'detain';if(['314','314.2'].includes(n))return 'detain';if(['228','228.1','231'].includes(n))return 'drugs';if(['222','222.3','226'].includes(n))return 'weapons';if(['139','213','213.1'].includes(n))return 'territory';let v=parseFloat(n);if(v>=331)return 'military';if(v>=294&&v<=316)return 'justice';if(v>=278&&v<=293)return 'service';if(v>=205&&v<278)return 'public';if(v>=158&&v<205)return 'property';return 'person'}
