 function upkGroup(x){let n=Number(x.number);if((n>=91&&n<=110)||[449,450].includes(n))return 'upk_detain';if(n>=29&&n<=72)return 'upk_rights';if(n>=73&&n<=226)return 'upk_investigation';return 'upk_other'}function fsbGroup(x){let n=Number(x.number);return n<=4?'fsb_general':n<=8?'fsb_activity':n<=16?'fsb_power':'fsb_control'}function pgoGroup(x){return {'Общие правила':'pgo_common','Задержание':'pgo_detain','Полномочия ФСБ':'pgo_fsb','Силовые структуры':'pgo_force','Суд и следствие':'pgo_sud','ГИБДД и ФСО':'pgo_traffic','RP-допрос':'pgo_interrogation','Обыск транспорта':'pgo_search'}[x.category]||'pgo_other'}
