 function rows(){return rowCache||(rowCache=[...[...ext.popular,...catalog].map(x=>({...x,group:group(x),code:'УК',id:'p'+x.number+'-'+x.part})),...refs.adminIndex.map(x=>{let full=refs.admin.find(a=>a.number===x.number);return {...x,...(full||{}),url:urls.koap,group:'admin',code:'КоАП',id:'adm'+x.number,part:'',stars:null,other:'',admin:true,reference:!full,term:full?.term||'Не добавлено'}}),...refs.upkIndex.map(x=>{let ref=refs.upk.find(a=>a.source==='Ст. '+x.number);return {...x,group:upkGroup(x),code:'УПК',id:'upk'+x.number,url:urls.upk,reference:true,part:'',stars:null,term:'—',other:ref?.text||'Краткое содержание пока не добавлено.'}}),...fsbIndex.map(x=>({...x,group:fsbGroup(x),code:'ФЗ ФСБ',id:'fsb'+x.number,url:fsbUrl,reference:true,part:'',stars:null,term:'—',other:fsbSummary[x.number]||'Подробное содержание пока не добавлено.'})),...charterItems,...pgo.map(x=>({...x,group:pgoGroup(x),code:'ПГО',id:'pgo'+x.number,reference:true,part:'',stars:null,term:'—',other:x.summary,directUrl:x.url}))])}

 function get(id){let x=rows().find(x=>x.id===id)||data.documents.find(x=>x.id===id)||data.articles.find(x=>x.id===id);if(!x && /^a/.test(id)){let n=id.slice(1);x=rows().find(x=>x.number===n)}return x}
