 function table(data,target){$(target).innerHTML=data.map(x=>{let star=x.admin||x.reference||x.stars===null?'—':x.stars===0?(x.starsText||'★–★★★★★'):'★'.repeat(x.stars);let term=x.reference?'—':x.admin?`Штраф ${x.term}`:`${x.term}${x.number==='314'||x.formula||x.fineOnly?'':' лишения свободы'}`;return `<article class="table-row"><div class="row-code"><span>${esc(x.code)} · ${esc(x.number)}</span>${x.part?`<small>часть ${esc(x.part)}</small>`:''}<small>${esc(jurisdiction(x))}</small></div><div class="row-title">${esc(x.title)}</div><div class="row-stars" aria-label="${x.admin?'КоАП, без звёзд':esc(star)}">${esc(star)}</div><div class="row-penalty">${esc(term)}${x.other?`<small>${esc(x.other)}</small>`:''}</div><div class="row-actions">${action(x.id)}${addButton(x.id)}<a href="${esc(itemSource(x))}" data-open="${esc(x.id)}" target="_blank" rel="noopener" aria-label="Открыть источник">↗</a></div></article>`}).join('')||'<p class="empty">Ничего не найдено. Попробуйте другой запрос.</p>'}
 const graphColors=['#d79183','#b6bc8e','#91b9b4','#a5a7cb','#c6a77d','#a0b1cb','#b99eb5','#94b4a1','#c6a39a','#a9b58f','#b9a5cc','#a9b7bd','#c3ab87'];
